({ I }) => {
  // 1. Xem chi tiết sản phẩm và thêm vào giỏ
  I.amOnPage('/product/1');
  I.waitForText('Thêm vào giỏ', 5);
  I.click('Thêm vào giỏ');

  // 2. Đi đến trang thanh toán
  I.amOnPage('/checkout');
  I.see('Thanh toán đơn hàng', 'h1');
  I.seeElement('//input[@placeholder="Họ tên người nhận"]');

  // 3. Nhập thông tin giao hàng
  I.fillField('//input[@placeholder="Họ tên người nhận"]', 'Nguyễn Văn A');
  I.fillField('//input[@placeholder="Số điện thoại"]', '0987654321');
  I.fillField('//input[@placeholder="Địa chỉ (số nhà, đường...)"]', 'Số 123 Đường Bee');
  I.fillField('//input[@placeholder="Phường / Xã"]', 'Phường Bến Nghé');
  I.fillField('//input[@placeholder="Quận / Huyện"]', 'Quận 1');
  I.fillField('//input[@placeholder="Tỉnh / Thành phố"]', 'TP. Hồ Chí Minh');
  I.fillField('//textarea[@placeholder="Ghi chú giao hàng (không bắt buộc)"]', 'Giao giờ hành chính');

  // 4. Chọn phương thức thanh toán và Đặt hàng
  // (Chúng ta có thể chọn phương thức COD - Nhận hàng thanh toán)
  I.click('Nhận hàng thanh toán (COD)');
  I.click('Xác nhận đặt hàng');

  // 5. Kiểm tra thông báo thành công
  I.waitForText('Đặt hàng thành công!', 10);
  I.see('Mã đơn hàng');
}

